"""Build one self-contained local representative review dashboard."""
import base64
import hashlib
import json
import sys
from pathlib import Path
from PIL import Image
ROOT=Path('.artifacts/soviet-remaining');EXPORT=ROOT/'review-exports-v3';OUT=ROOT/(sys.argv[1] if len(sys.argv)>1 else 'review-v1');OUT.mkdir(exist_ok=False)
report=json.loads((EXPORT/'report.json').read_text())
uri=lambda p:'data:image/png;base64,'+base64.b64encode(Path(p).read_bytes()).decode()
data=[]
for name,f in report['families'].items():
    item={k:v for k,v in f.items() if k not in ['motionMeasurements','registration']};item['id']=name
    for key in ['normal','original']:item[key]=uri(EXPORT/name/f[key])
    item['master']=uri(ROOT/'art-v1'/name/('normal-cutout-raw.png' if name in ['NANRCT','NAPSIS'] else 'normal-raw.png'))
    for s in item['sequences']:
        for frame in s['frames']:
            for key in ['hd','original']:frame[key]=uri(EXPORT/name/frame[key])
    data.append(item)
feedback=Path('.artifacts/m1-6b/feedback-r2')
fixes=[('Refinery: one conveyor',feedback/'runtime-refinery-v1/NAREFN/normal-4k-hd.png'),
       ('Continuous green placement footprint',feedback/'runtime-ui-v5/placement-valid-a.png'),
       ('One default-on HD switch',feedback/'runtime-ui-v5/hd-true.png')]
fixhtml=''.join(f'<figure><figcaption>{title}</figcaption><img src="{uri(p)}" alt="{title}"></figure>' for title,p in fixes)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Soviet Buildings — Material and Motion Review</title>
<style>
:root{color-scheme:dark;font:17px/1.5 system-ui;background:#17211e;color:#edf3ed}body{margin:0}header,main{max-width:1380px;margin:auto;padding:26px}h1{font-size:30px;line-height:1.2}h2{font-size:24px}h3{font-size:20px;margin:10px 0}p{max-width:1050px;color:#c9d5cf}button,select,input{font:inherit}button,select{padding:7px 12px;border:1px solid #697b70;background:#273a31;color:white;border-radius:5px;cursor:pointer}button:hover{background:#41604e}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;position:sticky;top:0;background:#17211ef2;padding:12px;z-index:2;border-block:1px solid #516159}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(560px,1fr));gap:22px}.card{background:#23322c;padding:20px;border:1px solid #4b5e51;border-radius:9px;min-width:0}.pair{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:15px;background:#34483d;min-height:280px;overflow:auto;padding:12px}.cell{text-align:center;flex:0 0 auto}.cell span{display:block;margin:8px;color:#d8e8dc}.cell img{display:block;margin:auto;object-fit:contain;max-width:none}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:14px 0}.frame{font-variant-numeric:tabular-nums;color:#d7eacc}.note{font-size:14px;color:#bac8c0}details{margin-top:15px}summary{cursor:pointer}.master{display:block;max-width:100%;max-height:750px;margin:auto;background:#34483d}.badge{font-size:14px;background:#66531e;padding:4px 9px;border-radius:4px;color:#fff5c9}table{border-collapse:collapse;font-size:15px;width:100%}td,th{text-align:left;border-bottom:1px solid #526259;padding:8px}.fixes{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr));gap:12px}.fixes figure{margin:0}.fixes img{width:100%;height:auto}.fixes figcaption{font-size:18px;padding:8px 0}.status{background:#243f30;border-left:4px solid #8ebba0;padding:14px}a{color:#b5d8ff}@media(max-width:620px){header,main{padding:12px}.cards{grid-template-columns:1fr}.pair{justify-content:flex-start}}
</style><header><h1>Soviet Buildings — Material and Motion Review</h1><span class="badge">REPRESENTATIVE REVIEW · AWAITING YOUR DECISION</span>
<p>All 13 remaining vanilla RA2 temperate Soviet building families. Each card compares Original with the authored HD candidate at the same source-canvas size. Use 1× for native sprite-pixel review, 2× to inspect details, or open the full material master.</p>
<p>These are representative candidates, not complete installed families. Eight-pose previews are labeled; intermediate frames, damaged states and final game integration still require production after this consolidated art decision. Existing accepted resources stay preserved. The playable correction app contains the five requested fixes and the accepted building set.</p>
<div class="status">Corrections: refinery render invariants PASS (61 matched pairs); one default-on HD switch PASS; Exit Game PASS; placement preview without internal grid PASS. Cursor coordinate/handoff tests PASS; physical macOS lock/unlock remains UNVERIFIED because automation could not obtain native window focus.</div></header>
<main><div class="toolbar"><label>View <select id="scale"><option value="1">1× native sprite pixels</option><option value="2">2× detail</option></select></label><label>Playback <select id="speed"><option value="1">1× source base rate</option><option value="0.25">¼× slow</option><option value="6">6× current capture rate</option></select></label><button id="materials">Show materials</button><button id="motions">Show motions</button><button id="pause">Pause all</button><label>Background <select id="background"><option value="#34483d">Green</option><option value="#c9c6b8">Light</option><option value="#141916">Dark</option></select></label><span id="count"></span></div>
<div class="cards" id="cards"></div><h2>Requested corrections</h2><div class="fixes">FIXHTML</div>
<h2>Review boundaries</h2><table><tr><th>Scope</th><th>Status</th></tr><tr><td>Previously accepted NAHAND, NAWEAP, NACNST and NAPOWR</td><td>Preserved; accepted</td></tr><tr><td>NAREFN conveyor correction</td><td>61 native Original/HD pairs PASS; visual confirmation requested</td></tr><tr><td>Remaining 13 building materials and representative motions</td><td>Pending your consolidated decision</td></tr><tr><td>Remaining families: all damage, buildup, repair, superweapon states; complete fallback; GPU budget; final playable integration</td><td>Not yet delivered; representative approval does not mark these complete</td></tr><tr><td>Physical cursor position in paused Options</td><td>Implementation and focused tests pass; hands-on Mac confirmation required</td></tr></table>
<p class="note">Motion controls come from the resolved retail members. HD color pixels come from the recorded authored masters. Isolated turret direction captures are reference fixtures, not production/gameplay proof. No campaign, gameplay rule, logical camera or accepted resource geometry changes are included.</p>
</main><script>const data=DATA;let scale=1,speed=1,paused=false;const players=[];
for(const f of data){const card=document.createElement('article');card.className='card';card.dataset.family=f.id;card.innerHTML=`<h2>${f.name} <small>(${f.id})</small></h2><div class="controls"><select class="mode"><option value="normal">Normal material</option>${f.sequences.map((s,i)=>`<option value="${i}">${s.label}</option>`).join('')}</select><button class="play">Pause</button><button class="prev">←</button><button class="next">→</button><span class="frame"></span></div><div class="pair"><div class="cell"><span>Original</span><img class="original" alt="${f.id} Original"></div><div class="cell"><span>HD candidate</span><img class="hd" alt="${f.id} HD"></div></div><input class="seek" type="range" min="0" value="0" style="width:100%;margin-top:12px"><p class="note coverage"></p><details><summary>Full material master</summary><img class="master" src="${f.master}" loading="lazy" alt="${f.id} authored master"></details><details><summary>Coverage and method</summary><p class="note method"></p><p class="note">Complete family: ${f.completeFamily}. Art decision: pending.</p></details>`;document.querySelector('#cards').append(card);
const p={f,card,index:0,mode:'normal',playing:true,time:0,normal:true};players.push(p);const q=s=>card.querySelector(s);p.draw=()=>{const seq=p.mode==='normal'?null:f.sequences[Number(p.mode)],frame=seq?.frames[p.index];q('.original').src=frame?.original??f.original;q('.hd').src=frame?.hd??f.normal;for(const img of [q('.original'),q('.hd')]){img.style.width=f.size[0]*scale+'px';img.style.height=f.size[1]*scale+'px'}q('.frame').textContent=seq?`${p.index+1}/${seq.frames.length} · ${seq.label==='turret-headings'?'Heading':'Native frame'} ${frame.sourceFrame}`:'Native-size material';q('.seek').max=(seq?.frames.length??1)-1;q('.seek').value=p.index;q('.seek').disabled=!seq;q('.coverage').textContent=seq?.coverage??'Authored normal material candidate. Open the master for a larger view.';q('.method').textContent=seq?.method??'Source-aware registration to the original canvas. No runtime override.';};q('.mode').onchange=e=>{p.mode=e.target.value;p.index=0;p.time=0;p.draw()};q('.play').onclick=()=>{p.playing=!p.playing;q('.play').textContent=p.playing?'Pause':'Play'};const step=delta=>{if(p.mode==='normal'){p.mode='0';q('.mode').value='0'}p.playing=false;q('.play').textContent='Play';const n=f.sequences[Number(p.mode)].frames.length;p.index=(p.index+delta+n)%n;p.draw()};q('.next').onclick=()=>step(1);q('.prev').onclick=()=>step(-1);q('.seek').oninput=e=>{p.playing=false;q('.play').textContent='Play';p.index=Number(e.target.value);p.draw()};p.draw();}
for(const [id,mode] of [['materials','normal'],['motions','0']])document.getElementById(id).onclick=()=>{for(const p of players){p.mode=mode;p.index=0;p.time=0;p.card.querySelector('.mode').value=mode;p.draw()}};
document.querySelector('#count').textContent=`${data.length} families · ${data.reduce((n,f)=>n+f.sequences.reduce((n,s)=>n+s.frames.length,0),0)} motion/state frames`;
document.querySelector('#scale').onchange=e=>{scale=Number(e.target.value);document.querySelector('.cards').style.gridTemplateColumns=scale===2?'1fr':'';players.forEach(p=>p.draw())};document.querySelector('#speed').onchange=e=>{speed=Number(e.target.value)};document.querySelector('#pause').onclick=e=>{paused=!paused;for(const p of players){p.playing=!paused;p.card.querySelector('.play').textContent=paused?'Play':'Pause'}e.target.textContent=paused?'Play all':'Pause all'};document.querySelector('#background').onchange=e=>{document.querySelectorAll('.pair,.master').forEach(p=>p.style.background=e.target.value);document.querySelectorAll('.cell span').forEach(p=>p.style.color=e.target.value==='#c9c6b8'?'#25382d':'#d8e8dc')};
let previous=performance.now();function animate(now){const dt=Math.min(.1,(now-previous)/1000);previous=now;for(const p of players){if(paused||!p.playing||p.mode==='normal')continue;const s=p.f.sequences[Number(p.mode)];p.time+=dt*speed*s.fps;if(p.time>=1){const n=Math.floor(p.time);p.time-=n;p.index=(p.index+n)%s.frames.length;p.draw()}}requestAnimationFrame(animate)}requestAnimationFrame(animate);window.__review={players,data};
</script></html>'''
(OUT/'review.html').write_text(page.replace('FIXHTML',fixhtml).replace('DATA',json.dumps(data,separators=(',',':'))))
print(OUT/'review.html',(OUT/'review.html').stat().st_size,'bytes')
